#!/usr/bin/env python3
"""The OPF site generator: the 9 opfiles.ai pages and the 3 reference CLI status lines, generated by the
opf/ tree from its own inputs through the OPF site renderer (_site_render.py beside this file).

  gen_draft_site.py --check               generate every declared output (GENERATED) and compare it with the
                                          committed bytes: exit 0 when all 12 match, 1 on drift, 2 when a
                                          page is refused or an input or output cannot be read
  gen_draft_site.py --out DIR             write every declared output under DIR, a new directory outside the
                                          OPF root, at its path relative to the OPF root (exit 0, or 2 with
                                          the reason)
  gen_draft_site.py --self-test           assert the declarations, the status lines, the drift check, repeat
                                          generation and an OPF-only copy, with no parent file
  gen_draft_site.py --parent-integration  with the parent repository's tools/gen_draft_site.py beside the OPF
                                          root, compare all 9 pages and all 3 status lines with that
                                          generator's bytes, the status lines in disposable copies

Ownership. While opf/ is nested in the parent repository, the parent's tools/gen_draft_site.py is the one
writer and the one drift gate of these 12 outputs. This generator never writes them in place: there is no
default write mode, and --out refuses a directory inside the OPF root. A difference between its bytes and
the committed bytes is a defect in this copy or a stale output, and --check reports it. Every input path is
named from the OPF root (the parent of this file's directory): the page data and committed pages under
site/, VERB_STATUS in tools/opf.py, and the 3 status line files. The renderer refuses a page data directory
that resolves outside the OPF root, and each file read must be a regular file, not a symbolic link; a
directory above a committed page, tools/opf.py or a status line file is followed as the file system
resolves it. Only --parent-integration reads a parent file.
"""
import sys

if tuple(sys.version_info[:2]) < (3, 14):
    import os
    try:
        sys.stderr.write(
            "error: gen_draft_site.py requires Python 3.14 or newer; this is Python %d.%d.%d (%s). "
            "Nothing was run (cannot evaluate).\n"
            % (tuple(sys.version_info[:3]) + (sys.executable or "unknown interpreter",)))
        sys.stderr.flush()
    except BaseException:
        pass
    os._exit(2)

import ast
import os
import shutil
import signal
import subprocess
import tempfile
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _site_render as render  # noqa: E402  (the OPF site renderer beside this file)

# The OPF root: every input and output path below resolves from it.
ROOT = render.ROOT

# The local declarations: the 9 pages (each relative to the OPF root) and the 3 status lines, each as (file,
# the prefix that names the line, the text before the note). Exactly 1 line of each file starts with its
# prefix; only that line is generated, and every other byte of the file is kept.
PAGES = (
    "site/index.html",
    "site/404.html",
    "site/adopt/index.html",
    "site/core-files/index.html",
    "site/draft/index.html",
    "site/disclosure/index.html",
    "site/license/index.html",
    "site/model/index.html",
    "site/standard/index.html",
)
_LLMS_ADOPT = ("- [Adopt](/adopt/): installing or adopting OPFiles is at /adopt/. Adopt with your AI development "
               "assistant through the `opf adopt` flow (investigate, propose one plan, take one approval, apply, "
               "verify), or create the plain-TOML store and wire its checks by hand. ")
STATUS_LINES = (
    ("README.md", render.STATUS_PREFIX, ""),
    ("spec/OPF-SPEC.md", render.STATUS_PREFIX, ""),
    ("site/llms.txt", "- [Adopt](/adopt/): ", _LLMS_ADOPT),
)
GENERATED = PAGES + tuple(rel for rel, _prefix, _lead in STATUS_LINES)

# --parent-integration only: the parent generator, relative to the directory holding the OPF root, and the
# prefix of the OPF root in that generator's output paths.
PARENT_GENERATOR = "tools/gen_draft_site.py"
PARENT_PREFIX = "opf/"


def status_files(tree=None, table=None):
    """{file: bytes} for each STATUS_LINES file under `tree` (default the OPF root), its 1 status line set to
    its text before the note followed by the status note of `table` (default VERB_STATUS in tools/opf.py
    under `tree`). RefusedPage when the table cannot be read, or a file cannot be read, is not a regular
    file, or has other than 1 line starting with its prefix."""
    tree = ROOT if tree is None else Path(tree)
    note = render.status_note(render.verb_status(tree) if table is None else table)
    outputs = {}
    for rel, prefix, lead in STATUS_LINES:
        try:
            data = render._existing(Path(tree) / rel)
            if data is None:
                raise OSError("it does not exist")
            text = data.decode("utf-8")
        except (OSError, UnicodeDecodeError) as exc:
            raise render.RefusedPage("{}: cannot read the status line file ({})".format(rel, exc))
        lines = text.split("\n")
        hits = [index for index, line in enumerate(lines) if line.startswith(prefix)]
        if len(hits) != 1:
            raise render.RefusedPage("{}: {} lines start with {!r}, not 1".format(rel, len(hits), prefix))
        lines[hits[0]] = lead + note
        outputs[rel] = "\n".join(lines).encode("utf-8")
    return outputs


def generate(tree=None):
    """{path relative to the OPF root: bytes} for every GENERATED output, from the inputs under `tree`
    (default the OPF root). RefusedPage when a page is refused or the built page set is not PAGES."""
    tree = ROOT if tree is None else Path(tree)
    pages = render.build(tree=tree)
    if set(pages) != set(PAGES):
        raise render.RefusedPage("built pages {} differ from PAGES {}".format(sorted(pages), sorted(PAGES)))
    outputs = {rel: pages[rel].encode("utf-8") for rel in PAGES}
    outputs.update(status_files(tree))
    return outputs


def check(tree=None):
    """Compare every generated output with the committed bytes under `tree`: 0 when all match, 1 on drift
    (a missing page is drift), 2 when a page is refused or an input or output cannot be read. A missing
    status line file is not drift but a refusal (2): its line is generated inside the committed file, so
    there is nothing to generate it from."""
    tree = ROOT if tree is None else Path(tree)
    try:
        outputs = generate(tree)
    except render.RefusedPage as exc:
        print("error: refused: {}".format(exc), file=sys.stderr)
        return 2
    drift = []
    for rel in GENERATED:
        try:
            current = render._existing(Path(tree) / rel)
        except OSError as exc:
            print("error: {}: {}".format(rel, exc), file=sys.stderr)
            return 2
        if current != outputs[rel]:
            drift.append(rel)
    for rel in drift:
        print("drift: {}".format(rel))
    if drift:
        print("while opf/ is nested, the parent repository's tools/gen_draft_site.py writes these files; a "
              "difference here is a defect in opf/tools/gen_draft_site.py or a stale output")
    return 1 if drift else 0


def write_out(dest, tree=None):
    """Write every generated output under `dest`, a directory that must not exist yet and must not resolve
    inside the OPF root `tree`, at its path relative to the OPF root: 0 written, 2 refused (nothing under
    the OPF root is ever written)."""
    tree = ROOT if tree is None else Path(tree)
    root = Path(os.path.realpath(tree))
    target = Path(os.path.realpath(dest))
    if target == root or root in target.parents:
        print("error: refused: {} is inside the OPF root {}; the parent generator is the one writer of the "
              "outputs there".format(dest, root), file=sys.stderr)
        return 2
    try:
        outputs = generate(tree)
    except render.RefusedPage as exc:
        print("error: refused: {}".format(exc), file=sys.stderr)
        return 2
    try:
        os.mkdir(dest)
        for rel in GENERATED:
            os.makedirs((Path(dest) / rel).parent, exist_ok=True)
            with open(Path(dest) / rel, "xb") as handle:
                handle.write(outputs[rel])
    except OSError as exc:
        print("error: cannot write under {} ({}); give a new directory".format(dest, exc), file=sys.stderr)
        return 2
    print("wrote {} files under {}".format(len(GENERATED), dest))
    return 0


# ---------------------------------------------------------------------------------------------------
# Parent integration: the parent generator's bytes, compared while it remains the owner.

FIXTURE_TABLE = (("a", "available", ""), ("b", "partial", "x, y"), ("c", "in progress", ""),
                 ("d", "in progress", ""))


def _load_parent():
    """The parent repository's generator, loaded by explicit path under a private module name (never
    registered in sys.modules under its own name, which this file shares). RefusedPage when it is absent."""
    path = ROOT.parent / PARENT_GENERATOR
    if ROOT.name + "/" != PARENT_PREFIX or not path.is_file():
        raise render.RefusedPage("no parent generator at {} beside the OPF root {}".format(path, ROOT))
    import importlib.util
    spec = importlib.util.spec_from_file_location("_opf_parent_gen_draft_site", path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def parent_integration():
    """0 when the parent generator's 9 OPF pages and its 3 status lines (for the live table and 2 fixture
    tables, each written by it into a disposable copy) equal this generator's bytes, 1 on a difference, 2
    when the parent generator cannot be loaded (it is absent, or loading it raises) or refuses (its own
    RefusedPage, a class distinct from the renderer's), or this generator refuses."""
    try:
        parent = _load_parent()
    except render.RefusedPage as exc:
        print("error: refused: {}".format(exc), file=sys.stderr)
        return 2
    except Exception as exc:  # any failure to load the parent is a refusal (2), never a traceback
        print("error: refused: cannot load the parent generator {} ({}: {})".format(
            ROOT.parent / PARENT_GENERATOR, type(exc).__name__, exc), file=sys.stderr)
        return 2
    parent_refused = getattr(parent, "RefusedPage", None)
    refusals = (render.RefusedPage,)
    if isinstance(parent_refused, type) and issubclass(parent_refused, Exception):
        refusals += (parent_refused,)
    try:
        parent_pages = parent.build()
        local = generate(ROOT)
    except refusals as exc:
        print("error: refused: {}".format(exc), file=sys.stderr)
        return 2
    findings = []
    opf_pages = sorted(rel[len(PARENT_PREFIX):] for rel in parent_pages if rel.startswith(PARENT_PREFIX))
    if opf_pages != sorted(PAGES):
        findings.append("parent pages {} differ from PAGES {}".format(opf_pages, sorted(PAGES)))
    for rel in PAGES:
        if parent_pages.get(PARENT_PREFIX + rel, "").encode("utf-8") != local[rel]:
            findings.append("page differs from the parent generator's: {}".format(rel))
    declared = tuple((rel[len(PARENT_PREFIX):], prefix, lead) for rel, prefix, lead in parent.STATUS_LINES)
    if declared != STATUS_LINES:
        findings.append("parent STATUS_LINES {!r} differ from STATUS_LINES".format(parent.STATUS_LINES))
    for name, table in (("live", None), ("fixture", FIXTURE_TABLE), ("fixture-one-pending", FIXTURE_TABLE[:3])):
        with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-parent-") as tmp:
            for rel, _prefix, _lead in STATUS_LINES:
                os.makedirs((Path(tmp) / PARENT_PREFIX / rel).parent, exist_ok=True)
                shutil.copyfile(ROOT / rel, Path(tmp) / PARENT_PREFIX / rel)
            code = parent.status_lines(tmp, False, table)
            try:
                mine = status_files(ROOT, table)
            except render.RefusedPage as exc:
                mine = {}
                findings.append("status ({}): refused here: {}".format(name, exc))
            for rel, _prefix, _lead in STATUS_LINES:
                with open(Path(tmp) / PARENT_PREFIX / rel, "rb") as handle:
                    theirs = handle.read()
                if code != 0 or mine.get(rel) != theirs:
                    findings.append("status line ({}) differs from the parent generator's: {} (parent exit "
                                    "{})".format(name, rel, code))
    for finding in findings:
        print("FAIL " + finding)
    if findings:
        return 1
    print("ok: the 9 pages and the 3 status lines equal the parent generator's bytes (status lines for the "
          "live table and 2 fixture tables)")
    return 0


# ---------------------------------------------------------------------------------------------------
# Self-test.

# The modules this file may import: the standard library and the renderer beside it; the parent generator
# is loaded by path in --parent-integration only.
_ALLOWED_IMPORTS = frozenset(("_site_render", "ast", "importlib.util", "os", "pathlib", "shutil", "signal",
                              "subprocess", "sys", "tempfile"))
_CHILD_TIMEOUT_SECONDS = 300


def _import_findings(source):
    """Every import in `source` outside _ALLOWED_IMPORTS (a relative import included)."""
    found = []
    for node in ast.walk(ast.parse(source)):
        if isinstance(node, ast.Import):
            found.extend("import {}".format(a.name) for a in node.names if a.name not in _ALLOWED_IMPORTS)
        elif isinstance(node, ast.ImportFrom):
            if node.level or node.module not in _ALLOWED_IMPORTS:
                found.append("from {}{} import".format("." * node.level, node.module or ""))
    return found


def _opf_only_copy(dest):
    """Copy into dest only what this generator reads: this file, the renderer and its inputs, and the 3
    status line files. Nothing of the parent repository is copied."""
    render._opf_only_copy(dest, tree=ROOT, script=Path(render.__file__))
    shutil.copyfile(Path(__file__), Path(dest) / "tools" / "gen_draft_site.py")
    for rel, _prefix, _lead in STATUS_LINES:
        os.makedirs((Path(dest) / rel).parent, exist_ok=True)
        shutil.copyfile(ROOT / rel, Path(dest) / rel)


def _run_child(script, args, cwd):
    """Run `script args` with -I -B as a child in its own session and process group from `cwd`; the group
    is killed when the child ends or times out. Returns (exit code or None on timeout, output)."""
    with subprocess.Popen([sys.executable, "-I", "-B", str(script)] + list(args), cwd=cwd,
                          stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                          start_new_session=True) as proc:
        try:
            out, _err = proc.communicate(timeout=_CHILD_TIMEOUT_SECONDS)
            code = proc.returncode
        except subprocess.TimeoutExpired:
            out, code = b"", None
        finally:
            try:
                os.killpg(proc.pid, signal.SIGKILL)
            except (ProcessLookupError, PermissionError):
                pass
            if proc.poll() is None:
                proc.wait()
    return code, out.decode("utf-8", "replace")


def _read(path):
    with open(path, "rb") as handle:
        return handle.read()


def _write(path, data):
    with open(path, "wb") as handle:
        handle.write(data)


def _self_test():
    failures = []
    count = [0]

    def expect(name, ok, detail=""):
        count[0] += 1
        if not ok:
            failures.append("{}: {!r}".format(name, detail))

    def refused(name, needle, callable_, *args):
        count[0] += 1
        try:
            callable_(*args)
        except render.RefusedPage as exc:
            if needle not in str(exc):
                failures.append("{}: refused without {!r}: {}".format(name, needle, exc))
            return
        failures.append("{}: not refused".format(name))

    # The local declarations: 9 pages (the renderer's set), 3 status line files, 12 outputs in all.
    expect("decl/nine-pages", len(set(PAGES)) == 9 and set(PAGES) == set(render.OPF_PAGES), PAGES)
    expect("decl/three-status-files", tuple(rel for rel, _p, _l in STATUS_LINES) == (
        "README.md", "spec/OPF-SPEC.md", "site/llms.txt"), STATUS_LINES)
    expect("decl/twelve-outputs", len(set(GENERATED)) == 12, GENERATED)

    # The live tree: every output generates as committed, twice the same, and --check is clean.
    try:
        first, second = generate(), generate()
    except render.RefusedPage as exc:
        first, second = {}, None
        failures.append("live/generate: refused: {}".format(exc))
    expect("live/repeat-identical", first == second and sorted(first) == sorted(GENERATED), sorted(first))
    for rel in GENERATED:
        try:
            committed = render._existing(ROOT / rel)
        except OSError as exc:
            committed = exc
        expect("live/as-committed " + rel, rel in first and first[rel] == committed, rel)
    expect("live/check-clean", check() == 0)

    # The status lines: the note from a table, only the prefixed line replaced, the llms.txt lead kept, and
    # a file without exactly 1 prefixed line, a missing file or a symbolic link refused.
    expect("status/note-text", render.status_note(FIXTURE_TABLE) == (
        "Reference CLI status. Available: a. Partial: b (x, y). In progress: c, d; each exits 2 in this build."),
        render.status_note(FIXTURE_TABLE))
    with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-status-") as tmp:
        for rel, prefix, _lead in STATUS_LINES:
            os.makedirs((Path(tmp) / rel).parent, exist_ok=True)
            _write(Path(tmp) / rel, "# T\n\n{}old\nkept\n".format(prefix).encode("utf-8"))
        try:
            got = status_files(tmp, FIXTURE_TABLE)
        except render.RefusedPage as exc:
            got = {"error": str(exc)}
        note = render.status_note(FIXTURE_TABLE)
        expect("status/line-replaced", got.get("README.md") == "# T\n\n{}\nkept\n".format(note).encode("utf-8"),
               got)
        expect("status/llms-lead", got.get("site/llms.txt") == "# T\n\n{}{}\nkept\n".format(
            _LLMS_ADOPT, note).encode("utf-8"), got)
        _write(Path(tmp) / "spec/OPF-SPEC.md", "# T\n{0}a\n{0}b\n".format(render.STATUS_PREFIX).encode("utf-8"))
        refused("status/two-lines-refused", "2 lines start", status_files, tmp, FIXTURE_TABLE)
        _write(Path(tmp) / "spec/OPF-SPEC.md", b"# T\nno line\n")
        refused("status/no-line-refused", "0 lines start", status_files, tmp, FIXTURE_TABLE)
        os.unlink(Path(tmp) / "spec/OPF-SPEC.md")
        refused("status/missing-refused", "does not exist", status_files, tmp, FIXTURE_TABLE)
        os.symlink(Path(tmp) / "README.md", Path(tmp) / "spec/OPF-SPEC.md")
        refused("status/symlink-refused", "not a regular file", status_files, tmp, FIXTURE_TABLE)

    # No competing writer: no default write mode, and --out refuses the OPF root and a directory inside it.
    with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-owner-") as tmp:
        tree = Path(tmp) / "opf"
        try:
            _opf_only_copy(tree)
            before = {rel: _read(tree / rel) for rel in GENERATED}
        except OSError as exc:
            before = {"error": str(exc)}
        expect("owner/no-default-write", main([]) == 2)
        codes = [write_out(tree / "site" / "gen", tree), write_out(tree, tree)]
        after = {rel: _read(tree / rel) for rel in GENERATED if (tree / rel).is_file()}
        expect("owner/out-inside-root-refused", codes == [2, 2] and not (tree / "site" / "gen").exists()
               and after == before, codes)
        os.makedirs(Path(tmp) / "taken")
        expect("owner/out-existing-refused", write_out(Path(tmp) / "taken", tree) == 2
               and os.listdir(Path(tmp) / "taken") == [])

    # Drift: a changed status line alone and a changed page alone are each drift (exit 1).
    for name, rel in (("check/status-drift", "README.md"), ("check/page-drift", "site/404.html")):
        with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-drift-") as tmp:
            tree = Path(tmp) / "opf"
            try:
                _opf_only_copy(tree)
                data = _read(tree / rel)
                prefix = render.STATUS_PREFIX.encode("utf-8")
                _write(tree / rel, data.replace(prefix, prefix + b"stale ", 1) if prefix in data else data + b"\n")
                code = check(tree)
            except OSError as exc:
                code = exc
            expect(name, code == 1, code)

    # Malformed page data: a component given as an array of names is refused (exit 2), never a crash.
    with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-malformed-") as tmp:
        tree = Path(tmp) / "opf"
        try:
            _opf_only_copy(tree)
            src = tree / render.SITE["src"]
            page = src / sorted(name for name in os.listdir(src) if name.endswith(".toml"))[0]
            text = _read(page).decode("utf-8")
            start = text.index('component = "')
            _write(page, (text[:start] + 'component = ["region"]' + text[text.index("\n", start):]).encode("utf-8"))
            code = check(tree)
        except (OSError, ValueError, IndexError) as exc:
            code = "cannot build the fixture: {}".format(exc)
        except Exception as exc:  # the crash this check guards against is its failure, not the run's
            code = "raised {}: {}".format(type(exc).__name__, exc)
        expect("check/component-array-refused", code == 2, code)

    # --parent-integration refuses (exit 2), never with a traceback, when the parent generator raises while
    # it loads or refuses with its own RefusedPage class (distinct from the renderer's). Each parent is a
    # stand-in written beside an OPF-only copy, which runs as a bounded child from an unrelated directory.
    stand_ins = (
        ("load-raises", 'raise RuntimeError("stand-in parent cannot load")\n', "cannot load the parent generator"),
        ("refuses", 'class RefusedPage(Exception):\n    pass\n\n\nSTATUS_LINES = ()\n\n\ndef build():\n'
                    '    raise RefusedPage("stand-in parent refuses")\n', "stand-in parent refuses"),
    )
    for name, body, needle in stand_ins:
        with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-parent-") as tmp:
            tree, elsewhere = Path(tmp) / "opf", Path(tmp) / "elsewhere"
            try:
                _opf_only_copy(tree)
                os.makedirs(elsewhere)
                os.makedirs((Path(tmp) / PARENT_GENERATOR).parent)
                _write(Path(tmp) / PARENT_GENERATOR, body.encode("utf-8"))
                code, out = _run_child(tree / "tools" / "gen_draft_site.py", ["--parent-integration"], elsewhere)
            except OSError as exc:
                code, out = None, "cannot build the stand-in parent: {}".format(exc)
            expect("parent/{}-refused".format(name), code == 2 and needle in out and "Traceback" not in out,
                   (code, out))

    # Imports: the standard library and the renderer only.
    with open(__file__, encoding="utf-8") as handle:
        source = handle.read()
    expect("imports/no-parent", _import_findings(source) == [], _import_findings(source))
    expect("imports/parent-import-found", _import_findings("import gen_mappings\nfrom _standards import x\n")
           == ["import gen_mappings", "from _standards import"])

    # An OPF-only copy, run from an unrelated directory: --check clean; a changed VERB_STATUS row is drift in
    # the 3 status lines; --out generates the outputs; with those written in place --check is clean again,
    # and a second --out gives the same bytes (repeat generation).
    with tempfile.TemporaryDirectory(prefix="opf-gen-draft-site-standalone-") as tmp:
        tree, elsewhere = Path(tmp) / "opf", Path(tmp) / "elsewhere"
        script = tree / "tools" / "gen_draft_site.py"
        os.makedirs(elsewhere)
        results = []
        try:
            _opf_only_copy(tree)
            results.append(_run_child(script, ["--check"], elsewhere))
            table = render.verb_status(tree)
            verb, status, scope = table[0]
            flipped = "in progress" if status != "in progress" else "available"
            source_text = _read(tree / render.STATUS_SOURCE).decode("utf-8")
            old, new = repr((verb, status, scope)), repr((verb, flipped, scope))
            if source_text.count(old) != 1:
                old = '("{}", "{}", "{}")'.format(verb, status, scope)
                new = '("{}", "{}", "{}")'.format(verb, flipped, scope)
            _write(tree / render.STATUS_SOURCE, source_text.replace(old, new, 1).encode("utf-8"))
            results.append(_run_child(script, ["--check"], elsewhere))
            results.append(_run_child(script, ["--out", str(Path(tmp) / "out1")], elsewhere))
            for rel in GENERATED:
                if (Path(tmp) / "out1" / rel).is_file():
                    shutil.copyfile(Path(tmp) / "out1" / rel, tree / rel)
            results.append(_run_child(script, ["--check"], elsewhere))
            results.append(_run_child(script, ["--out", str(Path(tmp) / "out2")], elsewhere))
            same = all((Path(tmp) / "out1" / rel).is_file() and _read(Path(tmp) / "out1" / rel)
                       == _read(Path(tmp) / "out2" / rel) for rel in GENERATED)
        except (OSError, ValueError, render.RefusedPage) as exc:
            results.append((None, "cannot run the OPF-only copy: {}".format(exc)))
            same = False
        codes = [code for code, _out in results]
        expect("standalone/check-clean", codes[:1] == [0], results[:1])
        status_drift = len(results) > 1 and all("drift: {}".format(rel) in results[1][1]
                                                for rel, _p, _l in STATUS_LINES)
        expect("standalone/status-input-drift", codes[1:2] == [1] and status_drift, results[1:2])
        expect("standalone/out-written", codes[2:3] == [0] and codes[4:5] == [0], results[2:5])
        expect("standalone/regenerated-check-clean", codes[3:4] == [0], results[3:4])
        expect("standalone/repeat-generation", same, codes)

    if failures:
        for failure in failures:
            print("FAIL " + failure, file=sys.stderr)
        print("{} of {} checks failed".format(len(failures), count[0]), file=sys.stderr)
        return 1
    print("ok: {} checks (the 9 pages and 3 status lines generate as committed and repeat, drift is named, "
          "nothing is written in place, a malformed page and a parent that fails to load or refuses exit 2, "
          "and an OPF-only copy generates and checks without the parent)".format(
              count[0]))
    return 0


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if argv == ["--self-test"]:
        return _self_test()
    if argv == ["--check"]:
        return check()
    if argv == ["--parent-integration"]:
        return parent_integration()
    if len(argv) == 2 and argv[0] == "--out":
        return write_out(argv[1])
    print("error: unrecognized arguments {!r} (use --check, --out DIR, --self-test or --parent-integration); "
          "nothing is written in place, the parent generator writes these outputs".format(argv), file=sys.stderr)
    return 2


# The child-status guard: an inline copy of the canonical guard in opf/tools/_child_status.py, which
# tools/check_child_status_coverage.py pins this copy to by AST. The self-test reads the exit status of the
# OPF-only copy it launches, so under an ignored SIGCHLD it would read a failing child as a pass; this
# generator refuses at its entry line instead, before main() runs.
# The status the probe child exits with; any value other than 0 and the refusal exit would do.
_CHILD_STATUS_PROBE_CODE = 77


def _child_status_refusal():
    """None when this process can read a child's exit status, otherwise the reason it cannot."""
    import os
    import signal
    if not hasattr(signal, "SIGCHLD"):
        return None
    disposition = signal.getsignal(signal.SIGCHLD)
    if disposition is not signal.SIG_DFL:
        return ("SIGCHLD is ignored (SIG_IGN) in this process" if disposition is signal.SIG_IGN
                else "SIGCHLD is not at its default disposition in this process")
    if not hasattr(os, "fork"):
        return None
    try:
        pid = os.fork()
    except OSError as exc:
        return "the child-status probe could not fork ({})".format(type(exc).__name__)
    if pid == 0:
        os._exit(_CHILD_STATUS_PROBE_CODE)
    try:
        waited, status = os.waitpid(pid, 0)
    except ChildProcessError:
        return "the probe child was reaped before its exit status could be read (ECHILD)"
    except OSError as exc:
        return "the probe child's exit status could not be read ({})".format(type(exc).__name__)
    if waited != pid or os.waitstatus_to_exitcode(status) != _CHILD_STATUS_PROBE_CODE:
        return "a probe child that exited {} was read back as wait status {}".format(
            _CHILD_STATUS_PROBE_CODE, status)
    return None


def _child_status_refusal_exit(name):
    """0 when a child's exit status is observable; otherwise write the named refusal and exit 2 at once
    (os._exit, so no exit-time stream flush can replace the status)."""
    import os
    reason = _child_status_refusal()
    if reason is None:
        return 0
    try:
        sys.stderr.write("error: {} refuses to run: {}, so a failed child would read as a success. Nothing "
                         "was run (cannot evaluate). Start it from a parent that leaves SIGCHLD at "
                         "SIG_DFL.\n".format(name, reason))
        sys.stderr.flush()
    except BaseException:
        pass
    os._exit(2)


if __name__ == "__main__":
    sys.exit(_child_status_refusal_exit("gen_draft_site.py") or main())
